-- 1002_import_opentdb_corpus.sql — insert the OpenTDB easy-band corpus.
--
-- GENERATED FILE — do not hand-edit. Rebuild with:
--   go run ./cmd/import -source opentdb && python3 data/opentdb_insert_build.py
--
-- WHY THIS IS DATA AND NOT JUST A LABEL
--   1001 restores difficulty ratings, whose true values the repo knows.
--   This file restores CONTENT. Upstream OpenTDB carries a question and
--   an answer but no options, and millionaire_questions.options requires
--   exactly four; the three distractors are synthesised from the same
--   category's other answers at import time (service/opentdb.go). A
--   database seeded any other way therefore has different options for the
--   same question, and this file is what makes them reproducible.
--
-- WHY IT MATTERS
--   Levels 1-3 draw from drawCasualBlend, which flips a coin between
--   WWTBAM@level and a casual pool that is source <> 'wwtbam'. With WWTBAM
--   as the only source the casual side is always empty and the blend
--   silently runs at 100/0 — every easy question from one source.
--
--   OpenTDB — https://opentdb.com — is CC BY-SA 4.0; attribution is in the
--   README. The categories vendored are those the casual blacklist allows:
--   no Entertainment:*, no Celebrities, no Science: Gadgets, no Mythology.
--   The distractors are SYNTHETIC — this is a known quality compromise,
--   not an oversight.
--
-- USAGE
--   psql "$DATABASE_URL" -f migrations/1002_import_opentdb_corpus.sql
--
-- Run AFTER 1001 (the ratings file covers WWTBAM only). Idempotent: rows
-- are skipped when a question with that exact text already exists, so
-- re-running imports 0. IDs are minted here with gen_random_uuid() rather
-- than baked in — every import run mints fresh UUIDs anyway, so a fixed ID
-- would be a lie about where the row came from.

BEGIN;

INSERT INTO millionaire_questions
    (id, question, options, correct_index, difficulty, category, source, strength)
